const subject = $('Gmail Trigger').item.json.subject ?? '';
const body = $('Gmail Trigger').item.json.text ?? $('Gmail Trigger').item.json.snippet ?? '';
const sender = $('Gmail Trigger').item.json.from?.value?.[0]?.address ?? '';

const keywordMatch = subject.match(/\[([^\]]+)\]/);
const keyword = keywordMatch ? keywordMatch[1].toLowerCase() : '';

const title = subject
  .replace(/smenso Task/i, '')
  .replace(/\[[^\]]+\]/g, '')
  .replace(/^[:\s]+/, '')
  .trim() || 'New Task from Email';

const projects = items.map(i => i.json);
const matchedProject = projects.find(p =>
  keyword && (p.title ?? p.name ?? '').toLowerCase().includes(keyword)
);

const defaultProjectId = 'YOUR_DEFAULT_PROJECT_ID_HERE';
const projectId = matchedProject?.id ?? defaultProjectId;
const projectName = matchedProject?.title ?? matchedProject?.name ?? 'Default Project';

return [{
  json: {
    title,
    description: `From: ${sender}\n\n${body}`,
    projectId,
    projectName,
    sender
  }
}];
